        "quote": "帕罗西汀/黛力新继续吃、不可停；阿普唑仑按需少量、短期"
      }
    ],
    "clinical_reasoning_direction": [
      {
        "event_id": "lite_evt_00112",
        "explanation": "医生根据家属反馈剩余药量和无高危信号，立即给出断药前三步路径，并将复诊/续方优先级动态调整，体现临床推理。",
        "quote": "先给您三条最稳的“断药前通道”，按顺序做"
      }
    ],
    "continuity_memory_focus": [
      {
        "event_id": "lite_evt_00199",
        "explanation": "医生在后续回复中再次确认旧药已吃当晚不补、过敏药不碰、记录模板等，保持对用药时间线和过敏史的持续追踪。",
        "quote": "如果今天早上已经吃过旧帕罗西汀和黛力新，今晚就不要再补吃"
      }
    ],
    "medical_safety_risk_recognition": [
      {
        "event_id": "lite_evt_00029",
        "explanation": "医生在首次回复中就询问了心慌频率、胸痛、晕厥等红旗信号，体现安全风险识别。",
        "quote": "有没有头晕或胸痛"
      }
    ],
    "patient_family_realworld_adaptation": [
      {
        "event_id": "lite_evt_00133",
        "explanation": "医生不仅建议预约，还提供代取药授权询问、本人到场策略，并帮家属准备转述话术以降低患者羞耻感和抵触。",
        "quote": "能代办就您跑，省得他抗拒"
      }
    ]
  },
